# -*- coding: utf-8 -*-
"""人物词典生成器（本项目的核心资产）。

设计
----
维基文库《史记》正文为**繁体**，而用户检索习惯用**简体**。
因此每个人物只登记「繁体别名」，由 OpenCC 自动补齐简体写法，
最终 aliases 同时包含繁简两套，做到：
    - 繁体正文可命中（匹配用繁体别名）
    - 简体输入可检索（name + 简体别名）

本文件的 PERSONS / CHAPTER_OWNERS 两张表就是 data/dict/people.json 的唯一来源。
改完执行：python build_dict.py

字段：id, 简体名, 繁体名, 朝代, 称号, 简介, [繁体别名...]
产物：data/dict/people.json + pipeline/_dict_report.json
"""
