# 《三王世家》通篇以「閎」「旦」「胥」相称）。全局收录该单字会误伤
# 「旦日」「不虞」「胥靡」这类普通词，因此限定只在指定篇目内匹配。
# 格式：(person_id, 单字, 限定篇目卷号列表)；卷号列表为 None 时取该人物的主人公篇目。
