# 分书收束泛称候选：同名帝号跨朝，断代史里裸称应优先本纪传统含义。
# 例：後漢書「武帝」= 漢武帝，不得因曹操时代更近而整书砸给曹操。
GENERIC_BOOK_CANDIDATES = {
    "武帝": {
        "sj": ["p_hanwudi"],
        "hs": ["p_hanwudi"],
        "hhs": ["p_hanwudi"],  # 后汉书追述几乎全指汉武帝；曹操用「魏武帝」
        "sgz": ["p_hanwudi", "p_caocao", "p_simayan"],
        # js 收束掉石虎、劉聰（2026-09 人工判定回填）：
        # 實測裸「武帝」歸石虎 99 處、劉聰 43 處，**沒有一篇在載記**——
        # 全在志（五行/地理）與列傳（宗室/四夷/外戚/儒林）裡，
        # 上下文是「武帝泰始二年」「武悼楊皇后配饗武帝廟」
        # 「武帝第二十五子也」「安世，武帝字也」——全是晉武帝司馬炎。
        # 石虎、劉聰是十六國君主，篇內共現把 chapter 檔拉過去所致。
        # 曹操改由「魏武帝」長名命中（books 已含 js），不留在裸稱候選裡更安全。
        "js": ["p_simayan", "p_hanwudi"],
    },
    "孝武帝": {
        "sj": ["p_hanwudi"],
        "hs": ["p_hanwudi"],
        "hhs": ["p_hanwudi"],
        "js": ["p_simayao"],
    },
    # 惠帝：晉書裸稱一律指晉惠帝司馬衷。漢惠帝用「漢惠帝/孝惠帝」長名。
    # 不收束時，篇內出現過「漢惠帝」長名 → 章信號倒向劉盈，實測 4 處誤歸。
    "惠帝": {
        "sj": ["p_hanhuidi"],
        "hs": ["p_hanhuidi"],
        "hhs": ["p_hanhuidi"],
        "sgz": ["p_hanhuidi"],
        "js": ["p_simazhong"],
    },
    # 元帝：晉書裸稱絕大多數指晉元帝司馬睿。魏元帝曹奐靠「魏元帝」長名（js 10 處）
    # 與「元帝+景元/咸熙」年號守衛（見 GENERIC_CONTEXT_RULES）命中。
    # 不收束時，志書篇內三國人物多 → era 檔把「元帝渡江」判給曹奐（實測 42 處裡多數錯）。
    "元帝": {
        "sj": ["p_hanyuandi"],
        "hs": ["p_hanyuandi"],
        "hhs": ["p_hanyuandi"],
        "sgz": ["p_caohuan", "p_hanyuandi"],
        # js 收束到司马睿：实测裸「元帝」在晋书 46 处落曹奐，其中只有「景元/咸熙」
        # 年号 6 处是真的，其余（渡江/中興/為丞相/分郁林…）全是晋元帝。
        # 曹奐改由长名（魏元帝）与年号守卫命中。
        # 劉奭**不**进 js 候选：试过加回来，結果司馬睿 289→263、漏标 2→11，
        # era 档「同代唯一」被破坏，得不偿失。漢代追述改由 ctxRule 定向命中——
        # ctxRule 是 ⓪ 级，在分书收束**之前**执行，只要 p_hanyuandi 的 books
        # 含 js（已含）就能越过这层收束，不需要脏候选表。
        "js": ["p_simarui"],
    },
}

# 泛称上下文守卫（P1，2026-09）：算法信号（owner/era/章…）判不出、或判错，
# 但**原文邻域**里有硬证据时用。用于「裸短名被截走 / 志书跨代误兜」两类。
# 规则形如 (邻域, 关键词, 目标 pid 或 None)：
#   post   —— 命中串之后 6 字内出现关键词（年号、谥号）
#   pre    —— 命中串之前 6 字内
#   window —— 前后各 12 字内
#   目标 None = 判不出，走 none（不标，宁缺勿滥）
# 目标必须在候选内（且过书作用域闸），否则规则不生效——避免越书硬归。
GENERIC_CONTEXT_RULES = {
    "高祖": [
        # 「高祖宣皇帝」是司马懿庙号+谥号；裸「高祖」被长名接管后仍可能有残余
        ("post", "宣皇帝", "p_simayi"),
        # 「高祖雍，曾祖柔」「臣高祖東莞太守雍」——这里的「高祖」是**高祖父**称谓，
        # 不是刘邦。句中出现「曾祖」即判不出（none）。
        ("window", "曾祖", None),
        ("window", "玄孫", None),
        # 「思高祖納婁敬之策」——婁敬是漢高祖謀士，這裡是漢典，指劉邦
        # （實測誤歸劉淵，見 docs/17-条目-晋书帝号.md 高祖 #4）。
        ("window", "婁敬", "p_liubang"),
        # 「無廢我高祖之景命」——晉室禪位詔書套語，高祖指晉高祖司馬懿
        # （實測 guess 兜到劉邦，見同文件 #1）。
        ("window", "景命", "p_simayi"),
    ],
    # 晉武帝年號：志書按年號紀年（「武帝泰始二年七月丙午晦，日有蝕之」），
    # 篇內時代混雜時 chapter 檔會互串，年號是硬證據。
    "武帝": [
        ("post", "泰始", "p_simayan"),
        ("post", "咸寧", "p_simayan"),
        ("post", "太康", "p_simayan"),
        ("post", "太熙", "p_simayan"),
    ],
    "元帝": [
        # 景元/咸熙 是魏元帝曹奐年号；太興/永昌/建武 是晋元帝司馬睿年号。
        # 志书（天文/五行/地理）按年号纪年，篇内时代混杂，era 档会互串。
        ("post", "景元", "p_caohuan"),
        ("post", "咸熙", "p_caohuan"),
        ("post", "太興", "p_simarui"),
        ("post", "永昌", "p_simarui"),
        ("post", "建武", "p_simarui"),
        # 「元帝渡江」「及元帝南遷」是晉元帝的標誌性事件。志書篇內時代混雜，
        # 加了劉奭進候選後 era 檔不再唯一、會掉到 guess，用這兩條把層級提回來。
        ("window", "渡江", "p_simarui"),
        ("window", "南遷", "p_simarui"),
        # 初元/永光/建昭/竟寧 是汉元帝刘奭年号（地理志「元帝初元三年，又罷珠崖郡」）
        ("post", "初元", "p_hanyuandi"),
        ("post", "永光", "p_hanyuandi"),
        ("post", "建昭", "p_hanyuandi"),
        ("post", "竟寧", "p_hanyuandi"),
        # 「元帝時，郎中京房知五音六十律」——京房是漢元帝時人（志第六），
        # 這是漢代追述，不是司馬睿（人工判定「对」，見 docs/17 元帝 #6）。
        ("window", "京房", "p_hanyuandi"),
    ],
}

# 默认归属覆盖：判不出上下文时兜底给谁。汉初「吳王」几乎都指刘濞、
# 「代王」多指刘恒，靠 PERSONS 次序取首位会反。
GENERIC_DEFAULT = {
    "吳王": "p_liupi",
    "代王": "p_hanwendi",
    # 吕后本纪「趙王」是如意/友/恢，不是张耳
    "趙王": "p_liuruyi",
    "梁王": "p_liuwu",
    # 多义「齊王」：战国/秦末/西汉。默认秦末田儋（先声明者）。
    # 三国曹芳不声明裸齐王（见 PERSONS），避免抢史汉命中。
    "齊王": "p_tian_dan",
    # 「文帝」已收曹丕 core（books=sgz），不再走泛称 default。
    "武帝": "p_simayan",
    "宣帝": "p_hanxuandi",
    "惠帝": "p_simazhong",
    "孝武帝": "p_simayao",
    "元帝": "p_simarui",
    "文王": "p_zhouwen",
    "武王": "p_zhouwu",
    "陳王": "p_caozhi",
    "關內侯": "p_pangde",
}


# ===== 《三国志》篇目主人公（键是卷 slug "01"–"65"；第 2 轮先列已有 pid）=====
# 国别体例：魏書·武帝紀 篇主=曹操。65 键必须齐（对齐 volumes/sgz.json）。
